--DS d_pick_ticket_oe_line_alloc
SELECT oe_line.order_no,inv_mast.item_id,oe_line.date_created,oe_line.date_last_modified,oe_line.last_maintained_by,oe_line.line_no,oe_line.qty_allocated,oe_line.source_loc_id,oe_line.supplier_id,oe_line.ASSEMBLY,oe_line.inv_mast_uid,oe_line.unit_of_measure,oe_line.unit_size,inv_mast.item_desc,inv_mast.track_lots,oe_line.disposition,oe_line.oe_line_uid,oe_line.parent_oe_line_uid,oe_line.qty_per_assembly,oe_line.qty_ordered,oe_line.detail_type,oe_line.lot_bill,oe_line.other_charge,oe_hdr.address_id,oe_line.company_no,oe_line.dea_restriction_failed,oe_line.routing_status_flag,oe_line.qty_invoiced,oe_line.qty_on_pick_tickets,oe_line.qty_canceled,inv_mast.item_type_cd,oe_line.peer_oe_line_uid,oe_line.scheduled,oe_line.expedite_date,DATEADD(DAY, -((COALESCE(p21_view_supplier_purchasing_info.average_lead_time, 0) * COALESCE(p21_view_supplier_purchasing_info.lead_time_safety_factor, 1)) + COALESCE(p21_view_supplier_purchasing_info.review_cycle, 0)), oe_line.expedite_date),oe_line.ship_loc_idFROM oe_lineINNER JOIN inv_mast ON ( inv_mast.inv_mast_uid = oe_line.inv_mast_uid )INNER JOIN oe_hdr ON ( oe_hdr.order_no = oe_line.order_no )INNER JOIN system_setting ON system_setting.name = 'expdt_date_use_item_lead_time'LEFT JOIN p21_view_supplier_purchasing_info ON ( p21_view_supplier_purchasing_info.supplier_id = oe_line.supplier_id ) AND( p21_view_supplier_purchasing_info.location_id = oe_line.source_loc_id ) AND( p21_view_supplier_purchasing_info.item_id = inv_mast.item_id ) AND( p21_view_supplier_purchasing_info.inv_mast_uid = inv_mast.inv_mast_uid ) AND( system_setting.value = 'Y' ) WHERE	( oe_line.order_no = '1092768' ) AND( oe_line.delete_flag = 'N' ) AND( oe_line.complete = 'N' ) AND( oe_line.scheduled = 'Y' ) AND( oe_line.disposition = '' OR oe_line.disposition IS NULL OR ( oe_line.disposition = 'C' AND oe_line.qty_allocated <> 0 ) ) AND( oe_line.detail_type <> 1 )